<script setup lang="ts">
import { onUnmounted, watch } from 'vue'
import type { ReviewWorkspaceApi, SessionData } from './client'
import { checkFields, conflictReasons, returnReasons, useReview } from './useReview'
const props = defineProps<{ api: ReviewWorkspaceApi; actor: SessionData }>()
const emit = defineEmits<{ sessionExpired: [] }>()
const model = useReview(props.api, () => emit('sessionExpired')), state = model.state
watch(() => props.actor, model.setActor, { immediate: true }); onUnmounted(model.dispose)
const labels: Record<typeof checkFields[number], string> = { original_value: '原始值', claim_kind: '声明类别', unit: '单位', period: '时间口径', scope: '适用范围', evidence_location: '证据定位', missingness: '缺失说明', footnote: '脚注', statistics_context: '统计上下文', date_context: '日期上下文' }
</script>
<template>
  <section class="rw-card" data-testid="review-panel" aria-labelledby="review-title" :aria-busy="!!state.busy">
    <h3 id="review-title">02 / 独立人工审核</h3><p>审核账号不能审核自己导入的候选。仅有限原文片段可见，无全附件权限；程序定位核对不能代替人工真实性判断。</p>
    <div class="rw-grid"><label>候选数据集 UUID<input v-model="state.datasetId" data-testid="review-dataset" :disabled="!!state.busy" @input="model.scopeChanged"></label><label>明确入学年度<input v-model="state.year" data-testid="review-year" type="number" min="1" max="9999" step="1" :disabled="!!state.busy" @input="model.scopeChanged"></label></div>
    <button type="button" data-testid="review-search" :disabled="!!state.busy" @click="model.search(false)">发现当前候选</button>
    <div v-if="state.page" class="rw-output"><p>数据集 revision {{ state.page.dataset_revision }} · 此页 {{ state.page.items.length }} 个候选</p><button v-for="item in state.page.items" :key="item.fact_id" type="button" :data-testid="`review-fact-${item.fact_id}`" :disabled="!!state.busy" @click="model.choose(item.fact_id)">{{ item.fact_id }} · {{ item.state }} · {{ item.entry_year }}</button><button type="button" data-testid="review-next-page" :disabled="!!state.busy || !state.page.next_cursor" @click="model.search(true)">下一页候选</button></div>
    <div class="rw-grid"><label>或指定候选 UUID<input v-model="state.factId" data-testid="review-fact-id" :disabled="!!state.busy" @input="model.factChanged"></label><button type="button" data-testid="review-load" :disabled="!!state.busy" @click="model.load">重新读取候选和 case</button></div>
    <p v-if="state.message" class="rw-message" :class="{ error: state.error }" :role="state.error ? 'alert' : 'status'">{{ state.message }}</p>
    <div v-if="state.detail" data-testid="review-detail">
      <p class="rw-boundary">{{ state.detail.fact.is_synthetic ? 'DEMO 合成候选' : '真实候选 / 仍需当前完整审核' }} · 原状态 {{ state.detail.fact.state }} · hard_rule=false / publication_eligible=false</p>
      <p>当前 case revision {{ state.detail.case.case_revision }} · 当前批准 {{ state.detail.case.current_approved ? '服务端当前批准' : '无当前有效批准' }} · 当前选择 {{ state.detail.case.chosen_fact_id ?? '无' }} · decision {{ state.detail.case.current_decision_id ?? '无' }}</p>
      <ul class="rw-gaps" data-testid="review-gaps"><li v-for="gap in state.detail.gaps" :key="gap">缺口 / {{ gap }}</li><li v-if="!state.detail.gaps.length">当前诊断无已知缺口；仍须逐项人工判断。</li></ul>
      <div class="rw-side-by-side">
        <section class="rw-output"><h4>候选原始字段与明确分类</h4><dl><div><dt>原值 / 类型</dt><dd>{{ state.detail.fact.value_text ?? `缺失/${state.detail.fact.missing_reason}` }} / {{ state.detail.fact.value_kind }}</dd></div><div><dt>规范值 / 原单位</dt><dd>{{ state.detail.fact.normalized_value ?? '未知' }} / {{ state.detail.fact.unit ?? 'null' }}</dd></div><div><dt>类别 / 规范单位</dt><dd>{{ state.detail.fact.classification.claim_kind }} / {{ state.detail.fact.classification.unit_code }}</dd></div><div><dt>时间口径</dt><dd>{{ state.detail.fact.classification.period }}</dd></div><div><dt>脚注</dt><dd>{{ state.detail.fact.footnote_state }} / {{ state.detail.fact.footnote_text ?? 'null' }}</dd></div><div><dt>统计人群 / 分母</dt><dd>{{ state.detail.fact.classification.statistic_population ?? '未知' }} / {{ state.detail.fact.classification.statistic_denominator ?? '未知' }}</dd></div><div><dt>届年 / 调查期</dt><dd>{{ state.detail.fact.classification.cohort_year ?? '未知' }} / {{ state.detail.fact.classification.survey_period ?? '未知' }}</dd></div></dl><p v-if="state.detail.fact.date_resolution">日期原精度 {{ state.detail.fact.date_resolution.precision }} · 时区 {{ state.detail.fact.date_resolution.timezone ?? '未知' }} · 状态 {{ state.detail.fact.date_resolution.conversion_status }} · 候选 UTC {{ state.detail.fact.date_resolution.calculated_utc_instant ?? '未知' }} · 正式 UTC=null</p><p v-else>没有日期 snapshot；不得补截止时间或 UTC。</p></section>
        <section class="rw-output"><h4>确切原文片段（最多 4096 UTF-8 字节）</h4><template v-if="state.detail.evidence"><pre data-testid="review-original">{{ state.detail.evidence.text }}</pre><p>byte [{{ state.detail.evidence.locator.byte_start }}, {{ state.detail.evidence.locator.byte_end }}) · 物理行 {{ state.detail.evidence.locator.line_start }}–{{ state.detail.evidence.locator.line_end }} · page/section=null</p><p>原文 SHA-256 <code>{{ state.detail.evidence.document_sha256 }}</code></p><p>片段 SHA-256 <code>{{ state.detail.evidence.snippet_sha256 }}</code></p></template><p v-else>缺少可读取证据，不能批准。</p></section>
      </div>
      <details open><summary>确切项目 / 年度 / 版本及全部 15 个范围键</summary><p>{{ state.detail.fact.offering_id }} / {{ state.detail.fact.offering_version }} / {{ state.detail.fact.entry_year }} · {{ state.detail.scope.country }}</p><dl class="rw-scope"><template v-for="(value, key) in state.detail.scope" :key="key"><div v-if="value && typeof value === 'object'"><dt>{{ key }}</dt><dd>{{ value.status }} / {{ value.value ?? 'null' }}</dd></div></template></dl></details>
      <fieldset :disabled="!!state.busy"><legend>逐项检查 · 初始均未选</legend><div class="rw-grid"><label v-for="field in checkFields" :key="field">{{ labels[field] }}<select v-model="state.checks[field]" :data-testid="`review-check-${field}`" @change="model.changed"><option disabled value="">本人明确判断</option><option value="accepted">接受</option><option value="rejected">拒绝</option><option value="not_applicable">不适用（仅确实未适用时）</option></select></label></div></fieldset>
      <div v-if="state.detail.conflicts.length" class="rw-output"><h4>全部当前冲突 · 不自动选择最高或最新</h4><div v-for="item in state.detail.conflicts" :key="item.fact_id"><p>{{ item.fact_id }} · {{ item.value_text ?? '缺失' }} {{ item.unit_text ?? '' }} · {{ item.classification.claim_kind }} · 脚注 {{ item.footnote_state }} / {{ item.footnote_text ?? 'null' }}</p><label>对该冲突的明确处理理由<select v-model="state.resolutions[item.fact_id]" :data-testid="`review-conflict-${item.fact_id}`" :disabled="!!state.busy" @change="model.changed"><option disabled value="">逐项选择，不能遗漏</option><option v-for="reason in conflictReasons" :key="reason" :value="reason">{{ reason }}</option></select></label></div></div>
      <div class="rw-grid"><label>本次决定<select v-model="state.action" data-testid="review-action" :disabled="!!state.busy" @change="model.changed"><option disabled value="">明确选择</option><option value="approve">批准当前候选</option><option value="return">退回，当前 case 批准失效</option></select></label><label v-if="state.action === 'return'">明确退回理由<select v-model="state.returnReason" data-testid="review-return-reason" :disabled="!!state.busy" @change="model.changed"><option disabled value="">选择有限理由</option><option v-for="reason in returnReasons" :key="reason" :value="reason">{{ reason }}</option></select></label></div>
      <label class="rw-check"><input v-model="state.confirmed" data-testid="review-confirm" type="checkbox" :disabled="!!state.busy"><span>本人已逐项判断并确认本次决定；不能由程序替代，也不会直接发布。</span></label><button type="button" data-testid="review-decide" :disabled="!model.canDecide()" @click="model.decide">确认提交审核决定</button>
    </div>
    <div v-if="state.decision" data-testid="review-decision-result" class="rw-output"><strong>{{ state.decision.action }} · 服务端决定 {{ state.decision.decision_id }}</strong><p>case revision {{ state.decision.case_revision }} · fact {{ state.decision.fact_id }} · 当前批准 {{ state.decision.current_approved }} · 尚未发布。</p></div>
  </section>
</template>
